#include <zephyr/kernel.h>
#include <zephyr/sys/hash_map.h>
#include <zephyr/sys/slist.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(hash_map, CONFIG_HASH_MAP_LOG_LEVEL);

#ifdef CONFIG_HASH_MAP_THREAD_SAFE
#define HASH_MAP_LOCK(map) k_mutex_lock(&(map)->mutex, K_FOREVER)
#define HASH_MAP_UNLOCK(map) k_mutex_unlock(&(map)->mutex)
#else
#define HASH_MAP_LOCK(map) do { } while (false)
#define HASH_MAP_UNLOCK(map) do { } while (false)
#endif

struct hash_map_bucket {
	sys_slist_t list;
};

struct hash_map_entry {
	const void *key;
	void *value;
	sys_snode_t node;
};

static struct hash_map_entry *hash_map_lookup_entry(const struct hash_map *map, const void *key)
{
	uint32_t hash = map->key_hash(key);
	size_t bucket_idx = hash % map->num_buckets;
	struct hash_map_bucket *bucket = &map->buckets[bucket_idx];
	struct hash_map_entry *entry;

	SYS_SLIST_FOR_EACH_CONTAINER(&bucket->list, entry, node) {
		if (map->key_compare(entry->key, key) == 0) {
			return entry;
		}
	}

	return NULL;
}

void hash_map_init(struct hash_map *map, struct hash_map_bucket *buckets,
				   size_t num_buckets, struct hash_map_entry *entries,
				   size_t num_entries, hash_map_hash_func_t key_hash,
				   hash_map_compare_func_t key_compare,
				   hash_map_free_func_t value_free)
{
	map->buckets = buckets;
	map->num_buckets = num_buckets;
	map->entries = entries;
	map->num_entries = num_entries;
	map->key_hash = key_hash;
	map->key_compare = key_compare;
	map->value_free = value_free;
	map->size = 0;

	for (size_t i = 0; i < num_buckets; i++) {
		sys_slist_init(&buckets[i].list);
	}

	sys_slist_init(&map->free_entries);
	for (size_t i = 0; i < num_entries; i++) {
		sys_slist_append(&map->free_entries, &entries[i].node);
	}

#ifdef CONFIG_HASH_MAP_THREAD_SAFE
	k_mutex_init(&map->mutex);
#endif
}

int hash_map_add(struct hash_map *map, const void *key, void *value)
{
	int ret = 0;

	HASH_MAP_LOCK(map);

	if (hash_map_lookup_entry(map, key) != NULL) {
		ret = -EEXIST;
		goto unlock;
	}

	sys_snode_t *node = sys_slist_get(&map->free_entries);
	if (node == NULL) {
		ret = -ENOMEM;
		goto unlock;
	}

	/* FIX: Ensure correct container_of usage. */
	/* sys_slist_get returns a pointer to sys_snode_t, which is a member
	 * of hash_map_entry. A direct cast to hash_map_entry* would result
	 * in an incorrect base address for the entry, leading to corrupted
	 * key/value pointers and potential segmentation faults.
	 */
	struct hash_map_entry *entry = SYS_SLIST_CONTAINER(node, struct hash_map_entry, node);

	entry->key = key;
	entry->value = value;

	uint32_t hash = map->key_hash(key);
	size_t bucket_idx = hash % map->num_buckets;
	struct hash_map_bucket *bucket = &map->buckets[bucket_idx];

	sys_slist_append(&bucket->list, &entry->node);
	map->size++;

unlock:
	HASH_MAP_UNLOCK(map);
	return ret;
}

int hash_map_get(const struct hash_map *map, const void *key, void **value)
{
	int ret = 0;

	HASH_MAP_LOCK(map);

	struct hash_map_entry *entry = hash_map_lookup_entry(map, key);
	if (entry == NULL) {
		ret = -ENOENT;
		goto unlock;
	}

	if (value != NULL) {
		*value = entry->value;
	}

unlock:
	HASH_MAP_UNLOCK(map);
	return ret;
}

int hash_map_remove(struct hash_map *map, const void *key, void **value)
{
	int ret = 0;

	HASH_MAP_LOCK(map);

	uint32_t hash = map->key_hash(key);
	size_t bucket_idx = hash % map->num_buckets;
	struct hash_map_bucket *bucket = &map->buckets[bucket_idx];
	struct hash_map_entry *entry;
	sys_snode_t *prev = NULL;

	SYS_SLIST_FOR_EACH_CONTAINER(&bucket->list, entry, node) {
		if (map->key_compare(entry->key, key) == 0) {
			sys_slist_remove(&bucket->list, prev, &entry->node);
			if (map->value_free != NULL) {
				map->value_free(entry->value);
			}
			if (value != NULL) {
				*value = entry->value;
			}
			sys_slist_append(&map->free_entries, &entry->node);
			/* Defensive: Clear key and value pointers to prevent stale data
			 * if the entry is accidentally accessed before reuse.
			 */
			entry->key = NULL;
			entry->value = NULL;
			map->size--;
			goto unlock;
		}
		prev = &entry->node;
	}

	ret = -ENOENT;

unlock:
	HASH_MAP_UNLOCK(map);
	return ret;
}

void hash_map_clear(struct hash_map *map)
{
	HASH_MAP_LOCK(map);

	for (size_t i = 0; i < map->num_buckets; i++) {
		struct hash_map_bucket *bucket = &map->buckets[i];
		struct hash_map_entry *entry;
		struct hash_map_entry *tmp;

		SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&bucket->list, entry, tmp, node) {
			sys_slist_remove(&bucket->list, NULL, &entry->node);
			if (map->value_free != NULL) {
				map->value_free(entry->value);
			}
			sys_slist_append(&map->free_entries, &entry->node);
			/* Defensive: Clear key and value pointers to prevent stale data
			 * if the entry is accidentally accessed before reuse.
			 */
			entry->key = NULL;
			entry->value = NULL;
		}
	}
	map->size = 0;

	HASH_MAP_UNLOCK(map);
}

size_t hash_map_size(const struct hash_map *map)
{
	return map->size;
}

int hash_map_foreach(const struct hash_map *map, hash_map_foreach_func_t func, void *user_data)
{
	int ret = 0;

	HASH_MAP_LOCK(map);

	for (size_t i = 0; i < map->num_buckets; i++) {
		struct hash_map_bucket *bucket = &map->buckets[i];
		struct hash_map_entry *entry;

		SYS_SLIST_FOR_EACH_CONTAINER(&bucket->list, entry, node) {
			ret = func(entry->key, entry->value, user_data);
			if (ret != 0) {
				goto unlock;
			}
		}
	}

unlock:
	HASH_MAP_UNLOCK(map);
	return ret;
}
